// Initialize the encoding state provided by the fuzzer runtime.
// The API requires a valid, writable pointer allocated by the caller; the
// runtime guarantees state_in is non-null and owned by this stub during call.
base64_init_encodestate(state_in);

// Track that this state has been initialized for encoding and is ready for a new sequence.
// Also clear any prior sequence markers.
FUZZ_SET_ATTR_INT(state_in, "enc_init", 1);
FUZZ_SET_ATTR_INT(state_in, "enc_started", 0);
FUZZ_SET_ATTR_INT(state_in, "enc_ended", 0);

// The state remains live and owned by the runtime pool after this stub, so return it as output.

// Generate a 6-bit value to satisfy the expected input domain [0, 63].
unsigned int raw = *FUZZ_PARAM(unsigned int);
char value_in = (char)(raw & 0x3F);
// Call the target function; return value is ignored here (no persistent objects involved).
volatile char out_ch = base64_encode_value(value_in);
(void)out_ch;

// Enforce that the state has been initialized and not finalized for the current sequence.
int enc_init = FUZZ_GET_ATTR_INT(state_in, "enc_init");
int enc_ended = FUZZ_GET_ATTR_INT(state_in, "enc_ended");
if (!enc_init || enc_ended) { FUZZ_BAIL(); }

// Produce random plaintext input. Cap size for performance.
std::string plaintext = FUZZ_PARAM_STR();
if (plaintext.size() > 1024) plaintext.resize(1024);
int length_in = (int)plaintext.size();

// Compute a safe maximum output size: ceil(n/3)*4. Add small slack.
int max_out = ((length_in + 2) / 3) * 4;
if (max_out < 0) { FUZZ_BAIL(); } // defensive overflow check
std::vector<char> out_buf((size_t)max_out + 8u, 0);

const char *plaintext_in = plaintext.data();
char *code_out = out_buf.data();

int written = base64_encode_block(plaintext_in, length_in, code_out, state_in);
// Validate bounds per API requirement.
FUZZ_ASSERT(written >= 0 && written <= (int)out_buf.size(), "base64_encode_block wrote out of bounds");

// Mark that a sequence has started.
FUZZ_SET_ATTR_INT(state_in, "enc_started", 1);

// Return the state so it remains in the pool.

// Must be called exactly once at the end of a sequence after init and zero or more blocks.
int enc_init = FUZZ_GET_ATTR_INT(state_in, "enc_init");
int enc_ended = FUZZ_GET_ATTR_INT(state_in, "enc_ended");
if (!enc_init || enc_ended) { FUZZ_BAIL(); }

// Provide a small, sufficient buffer (Base64 blockend typically emits up to 4 chars).
std::vector<char> out_buf(16, 0);
char *code_out = out_buf.data();

int written = base64_encode_blockend(code_out, state_in);
FUZZ_ASSERT(written >= 0 && written <= (int)out_buf.size(), "base64_encode_blockend wrote out of bounds");

// Mark the sequence as ended.
FUZZ_SET_ATTR_INT(state_in, "enc_ended", 1);
// Keep enc_init so the object is known as an initialized encodestate; a new sequence
// should re-init via base64_init_encodestate.

// Return the state to the pool.

// Initialize the decoding state provided by the fuzzer runtime.
base64_init_decodestate(state_in);

// Track decoder initialization and clear sequence markers.
FUZZ_SET_ATTR_INT(state_in, "dec_init", 1);
FUZZ_SET_ATTR_INT(state_in, "dec_started", 0);

// The state remains live; return it as output.

// Feed a random signed char, which may be in or out of the Base64 alphabet.
// Behavior for non-alphabet inputs is unspecified but should be handled by the implementation.
int v = (int)(*FUZZ_PARAM(unsigned int) & 0xFF);
signed char value_in = (signed char)(v - 128);
volatile signed char out_val = base64_decode_value(value_in);
(void)out_val;

// Ensure decodestate has been initialized.
int dec_init = FUZZ_GET_ATTR_INT(state_in, "dec_init");
if (!dec_init) { FUZZ_BAIL(); }

// Generate input code string; may include arbitrary bytes. Cap size for performance.
std::string code = FUZZ_PARAM_STR();
if (code.size() > 1024) code.resize(1024);
int length_in = (int)code.size();

// Worst-case decoded length is floor(n/4)*3 for valid input; allocate safely with slack.
int max_out = (length_in / 4) * 3 + 8;
if (max_out < 0) { FUZZ_BAIL(); }
std::vector<char> out_buf((size_t)max_out, 0);

const char *code_in = code.data();
char *plaintext_out = out_buf.data();

int written = base64_decode_block(code_in, length_in, plaintext_out, state_in);
FUZZ_ASSERT(written >= 0 && written <= (int)out_buf.size(), "base64_decode_block wrote out of bounds");

// Mark that decoding has started for this state instance.
FUZZ_SET_ATTR_INT(state_in, "dec_started", 1);

// Return the state as output.

// Allocate a decoder state owned by the fuzzer runtime after this stub returns.
struct base64_decodestate *state_out = (struct base64_decodestate *)std::malloc(sizeof(struct base64_decodestate));
if (!state_out) { FUZZ_BAIL(); }

// Initialize per API: must be called before any decode_block usage.
base64_init_decodestate(state_out);

// Track initialization and sequence status for downstream stubs.
FUZZ_SET_ATTR_INT(state_out, "dec_init", 1);
FUZZ_SET_ATTR_INT(state_out, "dec_started", 0);
// No need to mark ended; decoder API doesn't expose a dedicated end call here.

// state_out is returned as an initialized, writable, non-null decoder state.

// Allocate an encoder state owned by the fuzzer runtime after this stub returns.
struct base64_encodestate *state_out = (struct base64_encodestate *)std::malloc(sizeof(struct base64_encodestate));
if (!state_out) { FUZZ_BAIL(); }

// Initialize per API: must be called before any encode_block usage.
base64_init_encodestate(state_out);

// Track encoder lifecycle for downstream stubs.
FUZZ_SET_ATTR_INT(state_out, "enc_init", 1);
FUZZ_SET_ATTR_INT(state_out, "enc_started", 0);
FUZZ_SET_ATTR_INT(state_out, "enc_ended", 0);

