import random
import os
import struct
from typing import List

# This generator targets base64_encode_block fuzzing stub, which requests FUZZ_PARAM_STR
# representing arbitrary plaintext to be Base64-encoded. We generate valid binary payloads
# with varied lengths and content patterns to exercise different encoder paths, including
# all mod 3 length cases and diverse byte distributions.

def _weighted_choice(rng: random.Random, choices):
    total = sum(w for w, _ in choices)
    x = rng.uniform(0, total)
    upto = 0.0
    for w, val in choices:
        if upto + w >= x:
            return val
        upto += w
    return choices[-1][1]

def _gen_length(rng: random.Random) -> int:
    # Favor small lengths but include larger ones up to 1024 as per fuzzer cap.
    buckets = [
        (5, lambda: rng.randrange(0, 16)),        # very small
        (4, lambda: rng.randrange(16, 64)),       # small
        (3, lambda: rng.randrange(64, 256)),      # medium
        (2, lambda: rng.randrange(256, 768)),     # larger
        (1, lambda: rng.randrange(768, 1025)),    # near cap
    ]
    length = _weighted_choice(rng, [(w, f) for w, f in buckets])()

    # Occasionally force specific mod 3 values to exercise carry logic.
    if rng.random() < 0.5:
        mod_target = rng.choice([0, 1, 2])
        # adjust minimally to get desired mod class, keep within bounds
        cur_mod = length % 3
        delta = (mod_target - cur_mod) % 3
        new_len = length + delta
        if new_len <= 1024:
            length = new_len
        elif length >= delta:
            length -= (3 - delta) % 3
    return max(0, min(1024, length))

def _pattern_repeat(byte_val: int, length: int) -> bytes:
    return bytes([byte_val]) * length

def _pattern_increment(rng: random.Random, length: int, start: int = None, step: int = None) -> bytes:
    if start is None:
        start = rng.randrange(0, 256)
    if step is None:
        step = rng.choice([1, 3, 5, 17, 29, 127, 255])
    arr = bytearray(length)
    v = start
    for i in range(length):
        arr[i] = v & 0xFF
        v = (v + step) & 0xFF
    return bytes(arr)

def _pattern_blocks(rng: random.Random, length: int) -> bytes:
    # Compose random-sized blocks filled with specific bytes/patterns
    out = bytearray()
    while len(out) < length:
        remaining = length - len(out)
        block_len = min(remaining, rng.choice([1,2,3,4,8,12,16,24,32,48,64]))
        kind = rng.randrange(0, 6)
        if kind == 0:
            out += os.urandom(block_len)
        elif kind == 1:
            out += _pattern_repeat(0x00, block_len)
        elif kind == 2:
            out += _pattern_repeat(0xFF, block_len)
        elif kind == 3:
            out += _pattern_repeat(0x7F, block_len)
        elif kind == 4:
            out += _pattern_increment(rng, block_len)
        else:
            # ASCII-ish text with newlines and mixed whitespace
            alphabet = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789 +/\r\n\t\0"
            out += bytes(alphabet[rng.randrange(0, len(alphabet))] for _ in range(block_len))
    return bytes(out[:length])

def _pattern_structured(length: int) -> bytes:
    # Build a header + payload with little-endian counters to create structure
    header = bytearray()
    header += b"HDR1"  # 4 bytes signature
    header += struct.pack('<I', length & 0xFFFFFFFF)
    payload_len = max(0, length - len(header))
    return bytes(header) + bytes((i * 31 + 13) & 0xFF for i in range(payload_len))

def _compose_mix(rng: random.Random, length: int) -> bytes:
    if length == 0:
        return b""
    # Choose one primary pattern
    pattern = _weighted_choice(rng, [
        (3, 'random'),
        (2, 'repeat0'),
        (2, 'repeatFF'),
        (2, 'increment'),
        (3, 'blocks'),
        (1, 'structured'),
        (1, 'texty'),
    ])
    if pattern == 'random':
        data = os.urandom(length)
    elif pattern == 'repeat0':
        data = _pattern_repeat(0x00, length)
    elif pattern == 'repeatFF':
        data = _pattern_repeat(0xFF, length)
    elif pattern == 'increment':
        data = _pattern_increment(rng, length)
    elif pattern == 'blocks':
        data = _pattern_blocks(rng, length)
    elif pattern == 'structured':
        data = _pattern_structured(length)
    else:  # texty
        text = ("The quick brown fox jumps over the lazy dog.\n"
                "Base64 encode test input with CRLF endings.\r\n"
                "Null:\x00 and high-bytes will follow.")
        base = bytearray((text * ((length // len(text)) + 1)).encode('utf-8'))[:length]
        # sprinkle some high bytes
        for i in range(0, len(base), max(1, len(base)//17)):
            base[i] = (base[i] + 0x80) & 0xFF
        data = bytes(base)

    # Occasionally splice in boundary-specific tails to trigger step transitions.
    if length >= 1 and rng.random() < 0.35:
        # Ensure specific last 1-2 bytes patterns
        tail_kind = rng.choice(['zeroes', 'ff', '01', '7f00'])
        if tail_kind == 'zeroes' and length >= 2:
            data = data[:-2] + b"\x00\x00"
        elif tail_kind == 'ff' and length >= 2:
            data = data[:-2] + b"\xFF\xFF"
        elif tail_kind == '01' and length >= 2:
            data = data[:-2] + b"\x00\x01"
        elif tail_kind == '7f00' and length >= 2:
            data = data[:-2] + b"\x7F\x00"
        else:
            data = data[:-1] + b"\x00"
    return data

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    length = _gen_length(rng)
    data = _compose_mix(rng, length)
    # The fuzzer passes this as FUZZ_PARAM_STR; ensure the returned object is bytes.
    # Limit size per guidance (<=4096) and fuzzer cap (<=1024 already enforced).
    return data[:4096]
